), src AS (SELECT slug,name,display,
 CASE catc WHEN 'B' THEN 'c53b27fe-51d2-4179-a149-923aa1a718aa' WHEN 'A' THEN 'ded4299b-b9fe-4282-8b1e-d4a241a3fd8a' WHEN 'P' THEN 'fcfad8a5-06d3-467a-b266-683426d2a1f1' WHEN 'M' THEN '1829602e-89b9-4c2d-a3ec-dd597b0debbd' ELSE 'a63b84ff-ae21-437a-863c-37b10a029e9b' END::uuid AS cat,
 hs,pw,eff,algo,
 CASE coin WHEN 'BTC' THEN 'Bitcoin (BTC), Bitcoin Cash (BCH) and Bitcoin SV (BSV)' WHEN 'LTC' THEN 'Litecoin, Dogecoin, Bellscoin, Junkcoin, LuckyCoin and Pepecoin' WHEN 'ETC' THEN 'Ethereum Classic' WHEN 'XMR' THEN 'Monero' WHEN 'KAS' THEN 'Kaspa' WHEN 'KDA' THEN 'Kadena' WHEN 'CKB' THEN 'Nervos CKB' WHEN 'ZEC' THEN 'Zcash' WHEN 'DASH' THEN 'Dash' WHEN 'ALPH' THEN 'Alephium' WHEN 'HNS' THEN 'Handshake' ELSE 'Filecoin' END AS coins,
 CASE cool WHEN 'H' THEN 'Hydro / water cooling' WHEN 'I' THEN 'Immersion cooling' ELSE 'Air cooling' END AS cooling,
 CASE cool WHEN 'H' THEN 'a hydro (water-cooled) machine' WHEN 'I' THEN 'an immersion-cooled machine' ELSE 'an air-cooled machine' END AS cooldesc,
 CASE cool WHEN 'H' THEN 'Hydro units need a prepared coolant loop, manifold and dry cooler, and reward you with far quieter operation and much better efficiency retention in warm ambient conditions.' WHEN 'I' THEN 'Immersion units require a dielectric fluid tank and pump loop, run near silently, and hold rated efficiency even in high ambient temperatures.' ELSE 'Air-cooled units run at roughly 70-80 dB, which suits a garage, shed, warehouse or hosting facility rather than a living space, and they need clean intake air below 35C with non-recirculating exhaust.' END AS siteline,
 replace(pw,'W','') AS watts, price,stock,spec,imgs,infra,batch FROM src0)
INSERT INTO public.products (slug,name,brand,category_id,hashrate,power,efficiency,algorithm,condition,stock_status,price,sale_price,short_description,description,specs,images,featured)
SELECT slug,name,'Bitmain',cat,hs,pw,eff,algo,'New',stock,price,NULL,
 left(CASE WHEN infra THEN format('Factory-new %s Bitmain mining infrastructure. %s. Shipped worldwide from Hong Kong with full customs paperwork, warranty and crypto or bank payment.',display,spec)
  ELSE format('%s %s miner at %s and %s. New Bitmain stock, bench-tested, warranty, worldwide shipping from Hong Kong.',hs,algo,eff,pw) END,200),
 CASE WHEN infra THEN format(
'%1$s - factory-new Bitmain mining infrastructure in stock at Bitcoin Mining Depot, shipped worldwide from our Causeway Bay, Hong Kong facility. Configuration: %2$s.

This unit belongs to Bitmain''s industrial deployment line and is designed to sit behind a large ASIC fleet rather than beside a single miner. Buying it from Hong Kong puts you next to the factory and to the freight capacity that moves heavy electrical equipment, which is why landed cost and lead time are usually better than ordering the same equipment through a domestic reseller.

We supply the full commercial invoice pack, HS classification and packing list with every shipment, so your customs broker in the USA, Canada, Europe, Australia or anywhere else we deliver can clear it without delay. Duty, VAT and freight are itemised in your quote before you pay, so there is no surprise shipping charge after the fact.

Our engineering desk sizes %1$s against your available power, transformer capacity, rack layout and coolant loop before you order, and will tell you plainly if a smaller or larger configuration fits your site better. Payment is available in Bitcoin, USDT and other major cryptocurrencies, plus CashApp, Chime and bank transfer.

Warranty, spare parts and remote commissioning support are included with every order. If building a site is not practical, our hosting programme can place your fleet in a monitored industrial facility instead.',display,spec)
 ELSE format(
'%1$s - genuine Bitmain hardware in stock at Bitcoin Mining Depot and shipped worldwide from our Causeway Bay, Hong Kong warehouse. Every unit is bench-powered, hashrate-verified against factory specification and thermally checked before it is packed, so the machine that arrives is exactly the machine you paid for.

Performance and specifications: the %2$s runs the %3$s algorithm at %4$s while drawing approximately %5$s at the wall, giving a rated efficiency of %6$s. It is %7$s and mines %8$s. Efficiency - joules per unit of hashrate - is the number that decides whether a miner survives a difficulty increase, so compare %6$s against your electricity price before you commit capital.

Profitability and ROI: model it the honest way. Take daily revenue at current network difficulty, subtract (%9$s / 1,000 x 24 x your kWh rate), then divide the delivered cost by that daily margin to get payback in days. Machines in this class stay comfortably cash-flow positive under roughly $0.06/kWh and need careful modelling above $0.10/kWh. Send us your power rate and we will return a written projection at no cost.

Power and site requirements: plan a dedicated 200-240 V circuit with 20%% breaker headroom, because a standard 110 V residential outlet will not run this hardware. %10$s

Shipping, duty and payment: orders leave Hong Kong within 24-72 hours of cleared payment on express air freight with tracking, full customs documentation and double-boxed, foam-cradled packing with separately packed PSUs. We deliver to the USA, Canada, Europe, Australia and 100+ countries every week. Pay in Bitcoin, USDT and other major cryptocurrencies, or with CashApp, Chime and bank transfer, and duty and VAT are itemised up front.

Warranty and support: the %2$s ships with written warranty terms and DOA protection, and our in-house Hong Kong repair centre services hashboards, PSUs and control boards for the life of the machine. Free remote setup support covers pool configuration, firmware and tuning. Ordering three units or more? Use our wholesale desk for volume pricing and pallet freight, or ask about hosting if industrial power is not available at your site.',
 name,display,algo,hs,pw,eff,cooldesc,coins,watts,siteline) END,
 (jsonb_build_object('Brand','Bitmain','Model',display,'Condition','New - factory sealed','Warranty','Manufacturer warranty + Bitcoin Mining Depot repair support','Ships From','Causeway Bay, Hong Kong','Network','Ethernet RJ45','Voltage','200-240V AC')
  || CASE WHEN infra THEN jsonb_build_object('Configuration',spec)
     ELSE jsonb_build_object('Hashrate',hs,'Power Consumption',pw,'Efficiency',eff,'Algorithm',algo,'Cooling',cooling,'Mineable Coins',coins) END
  || CASE WHEN batch <> '' THEN jsonb_build_object('Shipping Batch',batch) ELSE '{}'::jsonb END),
 (SELECT array_agg('https://assets-www.bitmain.com.cn/shop-image-storage-s3/product/'||u) FROM unnest(imgs) u), (price > 8000 AND NOT infra)
FROM src
ON CONFLICT (slug) DO NOTHING;